import React from "react";

// S-capsule logo mark: top pill (white/black), diagonal parallelogram (light grey),
// bottom pill (black/orange).
export default function Logo({ size = 28, withWord = true, className = "" }) {
    const w = size;
    const h = size;
    return (
        <div className={`flex items-center gap-3 ${className}`} data-testid="brand-logo">
            <svg width={w} height={h} viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" aria-label="Studio Form logo">
                <g>
                    <path d="M15 10 H70 a18 18 0 0 1 0 36 H15 a18 18 0 0 1 0 -36 Z" fill="#FFFFFF" />
                    <path d="M42 10 H70 a18 18 0 0 1 0 36 H42 Z" fill="#0A0A0A" />
                    <path d="M15 10 H70 a18 18 0 0 1 0 -36 Z" stroke="#0A0A0A" strokeWidth="2" />
                </g>
                <path d="M22 44 L60 44 L78 56 L40 56 Z" fill="#D9D9D9" stroke="#0A0A0A" strokeWidth="2" strokeLinejoin="round" />
                <g>
                    <path d="M30 54 H85 a18 18 0 0 1 0 36 H30 a18 18 0 0 1 0 -36 Z" fill="#0A0A0A" />
                    <path d="M57 54 H85 a18 18 0 0 1 0 36 H57 Z" fill="#F47B3F" />
                    <path d="M30 54 H85 a18 18 0 0 1 0 36 H30 a18 18 0 0 1 0 -36 Z" stroke="#0A0A0A" strokeWidth="2" />
                </g>
            </svg>
            {withWord && (
                <span className="font-display font-bold text-white tracking-tight text-lg leading-none">
                    STUDIO<span className="text-brand-orange">FORM</span>
                </span>
            )}
        </div>
    );
}
